import { useCallback, useEffect, useState } from "react";
import { searchCyberSkills, getCyberSkill, type CyberSkill, type CyberSkillDetail } from "@/lib/cyber-skills/client";
import { getDivisionSkillConfig } from "@/lib/cyber-skills/division-registry";

export function useCyberSkills(initialQ = "", divisionId?: string) {
  const [q, setQ] = useState(initialQ);
  const [skills, setSkills] = useState<CyberSkill[]>([]);
  const [total, setTotal] = useState(0);
  const [domains, setDomains] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState<CyberSkillDetail | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const divisionLabel = divisionId ? getDivisionSkillConfig(divisionId)?.label : undefined;

  const search = useCallback(async (query?: string) => {
    setLoading(true);
    const result = await searchCyberSkills({
      q: query ?? q,
      division: divisionId,
      limit: 60,
    });
    if (result) {
      setSkills(result.skills);
      setTotal(result.filtered);
      setDomains(result.domains);
    }
    setLoading(false);
  }, [q, divisionId]);

  useEffect(() => { search(); }, [search]);

  const loadSkill = useCallback(async (name: string) => {
    setDetailLoading(true);
    const detail = await getCyberSkill(name);
    setSelected(detail);
    setDetailLoading(false);
  }, []);

  return { q, setQ, skills, total, domains, loading, search, selected, detailLoading, loadSkill, divisionLabel };
}
