/** Division → skill keyword registry (mirrors supabase/functions/_shared/division-skills.ts). */

export type DivisionSkillConfig = {
  divisionId: string;
  label: string;
  keywords: string[];
};

export const DIVISION_SKILL_REGISTRY: DivisionSkillConfig[] = [
  { divisionId: "soc", label: "Security Operations", keywords: ["soc", "siem", "incident response", "detection", "alert triage", "playbook"] },
  { divisionId: "threat-intel", label: "Threat Intelligence", keywords: ["threat intelligence", "apt", "ioc", "attribution", "mitre", "campaign"] },
  { divisionId: "red-team", label: "Penetration Testing & Red Team", keywords: ["pentest", "penetration", "red team", "exploit", "cobalt strike", "web application", "cors", "security headers"] },
  { divisionId: "blue-team", label: "Blue Team", keywords: ["detection engineering", "defensive", "hardening", "sigma", "siem rule", "blue team"] },
  { divisionId: "dfir", label: "Digital Forensics & IR", keywords: ["forensic", "dfir", "disk image", "memory forensics", "incident response", "timeline"] },
  { divisionId: "appsec", label: "Application Security", keywords: ["application security", "sast", "code review", "owasp", "devsecops", "secure coding"] },
  { divisionId: "cloud-security", label: "Cloud Security", keywords: ["cloud", "aws", "azure", "gcp", "kubernetes", "cspm", "iam"] },
  { divisionId: "vuln-mgmt", label: "Vulnerability Management", keywords: ["vulnerability", "cve", "patch", "cvss", "exploitability", "kev"] },
  { divisionId: "grc", label: "GRC", keywords: ["compliance", "risk assessment", "audit", "iso 27001", "soc 2", "pci"] },
  { divisionId: "consulting", label: "Security Consulting", keywords: ["security architecture", "vCISO", "executive", "assessment", "strategy"] },
  { divisionId: "ai-research", label: "AI & Security Research", keywords: ["machine learning", "ai security", "llm", "model", "adversarial", "atlas"] },
  { divisionId: "product-engineering", label: "Product Engineering", keywords: ["api security", "devsecops", "platform", "automation", "pipeline"] },
  { divisionId: "customer-success", label: "Customer Success", keywords: ["onboarding", "documentation", "integration", "runbook"] },
];

export function getDivisionSkillConfig(divisionId: string): DivisionSkillConfig | undefined {
  return DIVISION_SKILL_REGISTRY.find((d) => d.divisionId === divisionId);
}

/** Map workspace route prefix to division id. */
export function divisionFromPath(pathname: string): string | undefined {
  if (pathname.includes("/offensive/")) return "red-team";
  if (pathname.includes("/research/")) return "ai-research";
  if (pathname.includes("/ops/")) return "soc";
  if (pathname.includes("/defensive/")) return "blue-team";
  if (pathname.includes("/dfir/")) return "dfir";
  if (pathname.includes("/appsec/")) return "appsec";
  if (pathname.includes("/cloud/")) return "cloud-security";
  if (pathname.includes("/vulnerability/")) return "vuln-mgmt";
  if (pathname.includes("/grc/")) return "grc";
  if (pathname.includes("/consulting/")) return "consulting";
  if (pathname.includes("/engineering/")) return "product-engineering";
  if (pathname.includes("/success/")) return "customer-success";
  return undefined;
}
