import { authHeaders } from "@/lib/auth-adapter";

export type CyberSkill = {
  name: string;
  description: string;
  domain: string;
  path: string;
};

export type CyberSkillsSearchResult = {
  total: number;
  filtered: number;
  domains: string[];
  frameworks: string[];
  skills: CyberSkill[];
  source: string;
  license: string;
};

export type CyberSkillDetail = {
  name: string;
  content: string;
  source: string;
};

async function headers(): Promise<Record<string, string>> {
  return authHeaders();
}

export async function searchCyberSkills(opts: {
  q?: string;
  division?: string;
  domain?: string;
  limit?: number;
  offset?: number;
}): Promise<CyberSkillsSearchResult | null> {
  const cfg = getRuntimeConfig();
  const params = new URLSearchParams();
  if (opts.q) params.set("q", opts.q);
  if (opts.division) params.set("division", opts.division);
  if (opts.domain) params.set("domain", opts.domain);
  params.set("limit", String(opts.limit ?? 40));
  params.set("offset", String(opts.offset ?? 0));

  try {
    const res = await fetch(`${cfg.supabaseUrl}/functions/v1/cyber-skills-api?${params}`, {
      headers: await headers(),
    });
    if (!res.ok) return null;
    return await res.json();
  } catch {
    return null;
  }
}

export async function getCyberSkill(name: string): Promise<CyberSkillDetail | null> {
  const cfg = getRuntimeConfig();
  try {
    const res = await fetch(
      `${cfg.supabaseUrl}/functions/v1/cyber-skills-api?skill=${encodeURIComponent(name)}`,
      { headers: await headers() },
    );
    if (!res.ok) return null;
    return await res.json();
  } catch {
    return null;
  }
}

/** Extract MITRE technique IDs from skill markdown */
export function extractMitreIds(content: string): string[] {
  const matches = content.match(/T\d{4}(?:\.\d{3})?/g) ?? [];
  return [...new Set(matches)];
}
